class Solution {
public:
    int minMoves(int target, int maxDoubles) {
        long long moves = 0;
        long long t = target;
        while (maxDoubles > 0 && t > 1) {
            if (t % 2 == 0) {
                t /= 2;
                maxDoubles--;
            } else {
                t--;
            }
            moves++;
        }
        moves += t - 1;
        return (int)moves;
    }
};
